  const safeUrl = (u) => { try { const p = new URL(u); return (p.protocol === 'https:' || p.protocol === 'http:') ? p.href : null; } catch { return null; } };
  const link = (u, text, cls) => { const s = safeUrl(u); return s ? h('a', { href: s, target: '_blank', rel: 'noopener noreferrer nofollow', class: cls }, text) : h('span', {}, text); };
